    /**
     * @method
     * @description fetch open positions for a single market
     * @name weex#fetchPositionsForSymbol
     * @see https://www.weex.com/api-doc/contract/Account_API/GetSinglePosition
     * @description fetch all open positions for specific symbol
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/?id=position-structure}
     */
    public CompletableFuture<List<Position>> fetchPositionsForSymbol(Object symbol, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            Map<String, Object> market = this.market(symbol);
            Boolean sandboxMode = (Boolean) this.safeBool(this.options, "sandboxMode", false);
            if (java.util.Objects.equals(sandboxMode, true))
            {
                // the demo trading API does not provide a single-position endpoint
                return (this.fetchPositions(Helpers.toStringListArg(new ArrayList<Object>(Arrays.asList(market.get("symbol")))), parameters)).join();
            }
            Map<String, Object> request = new HashMap<String, Object>() {{
                put( "symbol", market.get("id") );
            }};
            List<Object> response = (this.contractPrivateGetCapiV3AccountPositionSinglePosition(this.extend(request, parameters))).join();
            return this.parsePositions(response, Helpers.toStringListArg(new ArrayList<Object>(Arrays.asList(market.get("symbol")))), new HashMap<String, Object>() {{}});
        }).thenApply(res -> ((List<?>) res).stream().map(Position::new).collect(Collectors.toList()));

    }

    public Object parsePosition(Map<String, Object> position, Map<String, Object> market)
    {
        //
        //     {
        //         "id": 737191855967437160,
        //         "asset": "USDT",
        //         "symbol": "DOGEUSDT",
        //         "side": "LONG",
        //         "marginType": "CROSSED",
        //         "separatedMode": "COMBINED",
        //         "separatedOpenOrderId": 0,
        //         "leverage": "20.00",
        //         "size": "300",
        //         "openValue": "27.96900",
        //         "openFee": "0.02237520",
        //         "fundingFee": "0",
        //         "marginSize": "100",
        //         "isolatedMargin": "0",
        //         "isAutoAppendIsolatedMargin": false,
        //         "cumOpenSize": "300",
        //         "cumOpenValue": "27.96900",
        //         "cumOpenFee": "0.02237520",
        //         "cumCloseSize": "0",
        //         "cumCloseValue": "0",
        //         "cumCloseFee": "0",
        //         "cumFundingFee": "0",
        //         "cumLiquidateFee": "0",
        //         "createdMatchSequenceId": 5762536243,
        //         "updatedMatchSequenceId": 5762741613,
        //         "createdTime": 1775760234825,
        //         "updatedTime": 1775763170789,
        //         "unrealizePnl": "0.00600",
        //         "liquidatePrice": "0"
        //     }
        //
        // watchPoisions
        //     {
        //         "id": "739004481374519656",
        //         "coin": "USDT",
        //         "symbol": "DOGEUSDT",
        //         "side": "LONG",
        //         "marginMode": "CROSSED",
        //         "separatedMode": "COMBINED",
        //         "separatedOpenOrderId": "0",
        //         "leverage": "11",
        //         "size": "100",
        //         "openValue": "9.31100",
        //         "openFee": "0.00744880",
        //         "fundingFee": "0",
        //         "isolatedMargin": "0",
        //         "autoAppendIsolatedMargin": false,
        //         "cumOpenSize": "100",
        //         "cumOpenValue": "9.31100",
        //         "cumOpenFee": "0.00744880",
        //         "cumCloseSize": "0",
        //         "cumCloseValue": "0",
        //         "cumCloseFee": "0",
        //         "cumFundingFee": "0",
        //         "cumLiquidateFee": "0",
        //         "createdMatchSequenceId": "5792711540",
        //         "updatedMatchSequenceId": "5792711540",
        //         "createdTime": "1776192398399",
        //         "updatedTime": "1776192398399"
        //     }
        //
        String errorMessage = this.safeString(position, "errorMsg");
        String errorCode = this.safeString(position, "errorCode");
        if (!java.util.Objects.equals(errorMessage, null))
        {
            this.handleOrderOrPositionError(errorCode, errorMessage, (Map<String, Object>) (position));
        }
        String marketId = this.fromSandboxMarketId(this.safeString2(position, "symbol", "coinId")); // coinId might be used in testnet: https://github.com/ccxt/ccxt/issues/28576#issuecomment-4439400273
        Map<String, Object> marketResolved = this.safeMarket(marketId, market, (String) null, "contract");
        Long timestamp = this.safeInteger(position, "createdTime");
        String marginType = this.safeString2(position, "marginType", "marginMode");
        String marginMode = "cross";
        if (java.util.Objects.equals(marginType, "ISOLATED"))
        {
            marginMode = "isolated";
        }
        String separatedMode = this.safeString(position, "separatedMode");
        Boolean hedged = null;
        if (java.util.Objects.equals(separatedMode, "COMBINED"))
        {
            hedged = false;
        } else if (java.util.Objects.equals(separatedMode, "SEPARATED"))
        {
            hedged = true;
        }
        String notional = this.safeString(position, "openValue");
        String size = this.safeString(position, "size");
        String entryPrice = Precise.stringDiv(notional, size);
        return this.safePosition(Helpers.newMap(
            "symbol", marketResolved.get("symbol"),
            "id", this.safeString2(position, "id", "positionId"),
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "contracts", this.parseNumber(size),
            "contractSize", null,
            "side", this.safeStringLower(position, "side"),
            "notional", this.parseNumber(notional),
            "leverage", this.safeNumber(position, "leverage", (Object) null),
            "unrealizedPnl", this.safeNumber(position, "unrealizePnl", (Object) null),
            "realizedPnl", null,
            "collateral", null,
            "entryPrice", this.parseNumber(entryPrice),
            "markPrice", null,
            "liquidationPrice", this.safeNumber(position, "liquidatePrice", (Object) null),
            "marginMode", marginMode,
            "hedged", hedged,
            "maintenanceMargin", null,
            "maintenanceMarginPercentage", null,
            "initialMargin", this.safeNumber(position, "marginSize", (Object) null),
            "initialMarginPercentage", null,
            "marginRatio", null,
            "lastUpdateTimestamp", this.safeInteger(position, "updatedTime"),
            "lastPrice", null,
            "stopLossPrice", null,
            "takeProfitPrice", null,
            "percentage", null,
            "info", position
        ));
    }

